-- INTAKE-02: the no-consent scoping rule leaves F-36 D open ("Do you have any other concerns?"
-- is the reviewer's own field, and a waiver can raise concerns). The seed does the same update,
-- but deploys (vercel-build) run migrations only, not the seed.
--
-- Updated only while the setting still holds the INTAKE-01 seeded value, compared as jsonb (key
-- order does not matter, array order does). A value REC Staff changed on /admin/settings, or a
-- database that has no setting yet (the seed creates it with the new value), is left alone.
UPDATE "settings"
SET "value" = $rules$[{"id":"minors-icf","when":{"===":[{"var":"scoping.minors"},false]},"form":"F-36","codes":["A.07"],"reason":"no minors among the participants"},{"id":"focus-groups","when":{"===":[{"var":"scoping.focusGroups"},false]},"form":"F-36","codes":["A.17"],"reason":"no focus group discussions"},{"id":"online-consent","when":{"===":[{"var":"scoping.onlineConsent"},false]},"form":"F-36","codes":["A.25"],"reason":"consent is not given online"},{"id":"translated-icf","when":{"===":[{"var":"scoping.nonEnglishIcf"},false]},"form":"F-36","codes":["B.02"],"reason":"every participant reads the English ICF"},{"id":"faculty-initiated","when":{"===":[{"var":"scoping.facultyInitiated"},false]},"form":"F-35","codes":["2.02"],"reason":"not a faculty-initiated study"},{"id":"personal-data","when":{"===":[{"var":"scoping.personalData"},false]},"form":"F-35","codes":["3.02","3.03","3.04","3.05","3.06","3.07","3.08","3.09","3.10"],"reason":"no personal or sensitive data is collected"},{"id":"no-consent","when":{"===":[{"var":"scoping.consentNeeded"},false]},"form":"F-36","allExcept":["1","1.NO","D"],"reason":"informed consent is not sought ({waiverReason})"}]$rules$::jsonb,
    "updated_at" = NOW()
WHERE "key" = 'intake.scopingRules'
  AND "value"::jsonb = $rules$[{"id":"minors-icf","when":{"===":[{"var":"scoping.minors"},false]},"form":"F-36","codes":["A.07"],"reason":"no minors among the participants"},{"id":"focus-groups","when":{"===":[{"var":"scoping.focusGroups"},false]},"form":"F-36","codes":["A.17"],"reason":"no focus group discussions"},{"id":"online-consent","when":{"===":[{"var":"scoping.onlineConsent"},false]},"form":"F-36","codes":["A.25"],"reason":"consent is not given online"},{"id":"translated-icf","when":{"===":[{"var":"scoping.nonEnglishIcf"},false]},"form":"F-36","codes":["B.02"],"reason":"every participant reads the English ICF"},{"id":"faculty-initiated","when":{"===":[{"var":"scoping.facultyInitiated"},false]},"form":"F-35","codes":["2.02"],"reason":"not a faculty-initiated study"},{"id":"personal-data","when":{"===":[{"var":"scoping.personalData"},false]},"form":"F-35","codes":["3.02","3.03","3.04","3.05","3.06","3.07","3.08","3.09","3.10"],"reason":"no personal or sensitive data is collected"},{"id":"no-consent","when":{"===":[{"var":"scoping.consentNeeded"},false]},"form":"F-36","allExcept":["1","1.NO"],"reason":"informed consent is not sought ({waiverReason})"}]$rules$::jsonb;
